 total:=jsonb_array_length(public.lm_workspace()->'expenses');
 begin perform public.lm_save_expense_batch('[{"category":"Studio","description":"Valid","amount":20},{"category":"Studio","description":"Invalid","amount":0}]',null,null,null);raise exception 'Invalid row accepted';exception when raise_exception then if sqlerrm<>'Each expense needs a description and a positive amount' then raise;end if;end;
 if jsonb_array_length(public.lm_workspace()->'expenses')<>total then raise exception 'Batch saved partly';end if;
 perform public.lm_save_expense_batch('[{"category":"Studio","description":"Bank transfer","amount":1}]','2026-10-07','Muskan','Bank transfer');
 c:=(public.lm_save_record('customers','{"name":"Delete rollback client"}',null)->>'id')::uuid;ids:=ids||jsonb_build_object('customers',c);
