 if not exists(select 1 from jsonb_array_elements(public.lm_workspace()->'orders') o where o->>'id'=oid::text and o->>'trials'='2 trials' and o->>'fitting_date' is null) then raise exception 'Manual Trials missing';end if;
 piece:=(public.lm_save_record('studio_pieces','{"name":"Delete piece","kind":"Samples","quantity":1,"status":"New Order"}',null)->>'id')::uuid;ids:=ids||jsonb_build_object('studio_pieces',piece);
 ids:=ids||jsonb_build_object('purchases',(public.lm_save_record('purchases',jsonb_build_object('purchase_date','2026-10-07','vendor','Vendor','item','Organza','category','Fabric','quantity',1,'amount',100,'status','Paid','order_id',oid,'studio_piece_id',piece),null)->>'id')::uuid);
 ids:=ids||jsonb_build_object('expenses',(public.lm_save_record('expenses',jsonb_build_object('expense_date','2026-10-07','description','Courier','category','Courier','amount',10,'payment_mode',null,'order_id',oid),null)->>'id')::uuid);
