 ids:=ids||jsonb_build_object('tasks',(public.lm_save_record('tasks',jsonb_build_object('title','Linked task','task_date','2026-10-07','customer_id',c,'order_id',oid),null)->>'id')::uuid);
 ids:=ids||jsonb_build_object('events',(public.lm_save_record('events',jsonb_build_object('title','Linked event','event_date','2026-10-07','order_id',oid),null)->>'id')::uuid);
 ids:=ids||jsonb_build_object('alterations',(public.lm_save_record('alterations',jsonb_build_object('order_id',oid,'issue','Fit','received_date','2026-10-07','status','Received'),null)->>'id')::uuid);
 salary:=(public.lm_save_record('salaries','{"staff_name":"Rollback salary","salary":1000,"frequency":"Monthly","period_start":"2026-10-01","period_end":"2026-10-31","deduction":0}',null)->>'id')::uuid;ids:=ids||jsonb_build_object('salaries',salary);
 ids:=ids||jsonb_build_object('salary_payments',(public.lm_save_record('salary_payments',jsonb_build_object('salary_id',salary,'payment_date','2026-10-07','amount',100,'kind','Salary','payment_mode','Cash'),null)->>'id')::uuid);
 profile:=(public.lm_save_record('salary_profiles','{"staff_name":"Rollback profile","amount":100,"frequency":"Weekly"}',null)->>'id')::uuid;ids:=ids||jsonb_build_object('salary_profiles',profile);
 ids:=ids||jsonb_build_object('salary_payouts',(public.lm_save_record('salary_payouts',jsonb_build_object('profile_id',profile,'payment_date','2026-10-07','amount',100,'payment_mode','Cash'),null)->>'id')::uuid);
 ids:=ids||jsonb_build_object('inventory',(public.lm_save_record('inventory','{"sku":"ROLLBACK-DELETE","name":"Thread","quantity":1,"unit":"Pieces","category":"Trims","reorder_level":0,"cost":10}',null)->>'id')::uuid);
 ids:=ids||jsonb_build_object('influencer_marketing',(public.lm_save_marketing('{"influencer_name":"Delete influencer","outfit_name":"Top","collaboration":"Barter","status":"Sent"}',null)->>'id')::uuid);
 for row in select key,value#>>'{}' id from jsonb_each(ids) loop
  before:=public.lm_workspace();preview:=public.lm_delete_preview(row.key,row.id::uuid);
  archive:=(public.lm_delete_record(row.key,row.id::uuid,preview->>'token')->>'archive_id')::uuid;
  if row.key='customers' and ((before->'home'->>'sales')::numeric-(public.lm_workspace()->'home'->>'sales')::numeric<>2000 or (before->'home'->>'collected')::numeric-(public.lm_workspace()->'home'->>'collected')::numeric<>500) then raise exception 'Deletion did not update financial totals';end if;
  if exists(select 1 from jsonb_array_elements(coalesce(public.lm_workspace()->row.key,'[]')) r where r->>'id'=row.id) then raise exception 'Delete failed for %',row.key;end if;
  perform public.lm_restore_record(archive);after:=public.lm_workspace();
  if not exists(select 1 from jsonb_array_elements(coalesce(after->row.key,'[]')) r where r->>'id'=row.id) then raise exception 'Restore failed for %',row.key;end if;
  if before->'home' is distinct from after->'home' then raise exception 'Restore changed totals for %',row.key;end if;
 end loop;
 preview:=public.lm_delete_preview('customers',c);
 if (preview->'counts'->>'orders')::int<>1 or (preview->'counts'->>'order_payments')::int<>1 or (preview->'counts'->>'purchase_payments')::int<>1 then raise exception 'Linked deletion scope incomplete';end if;
 begin perform public.lm_delete_record('customers',c,'stale');raise exception 'Stale confirmation accepted';exception when raise_exception then if sqlerrm<>'This entry changed. Review Delete again before confirming.' then raise;end if;end;
 if has_function_privilege('anon','public.lm_delete_record(text,uuid,text)','execute') then raise exception 'Anonymous delete allowed';end if;
end $$;
